#include <queue>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <set>

using namespace std;

#define INF 1e18
#define int long long
typedef pair<int, int> P;
#define MP make_pair

int n, m, k, s, p, q;
unordered_map<int, vector<int>> pairs;
vector<int> zonbi, dis, costco;
set<P> pq;

signed main() {
    cin >> n >> m >> k >> s >> p >> q;
    zonbi.resize(k);
    dis.resize(n + 1, INF);
    costco.resize(n + 1, INF);

    for (int i = 0; i < k; i++) {
        cin >> zonbi[i];
    }

    for (int i = 0; i < m; i++) {
        int x, y;
        cin >> x >> y;
        pairs[x].push_back(y);
        pairs[y].push_back(x);
    }

    for (int i = 0; i < k; i++) {
        pq.insert(MP(0, zonbi[i]));
        dis[zonbi[i]] = 0;
    }

    while (!pq.empty()) {
        int cost = pq.begin()->first;
        int start = pq.begin()->second;
        pq.erase(pq.begin());
        if (s == cost) continue;

        for (int j : pairs[start]) {
            if (dis[j] > cost + 1) {
                dis[j] = cost + 1;
                pq.insert(MP(cost + 1, j));
            }
        }
    }

    pq.insert(MP(0, 1));
    costco[1] = 0;

    while (!pq.empty()) {
        int cost = pq.begin()->first;
        int start = pq.begin()->second;
        pq.erase(pq.begin());

        for (int i : pairs[start]) {
            int hoge;
            if (dis[i] == 0) {
                continue;
            } else if (dis[i] == INF) {
                hoge = p;
            } else {
                hoge = q;
            }

            if (i == n) {
                hoge = 0;
            }

            if (costco[i] > cost + hoge) {
                costco[i] = cost + hoge;
                pq.insert(MP(cost + hoge, i));
            }
        }
    }

    cout << costco[n] << endl;
    return 0;
}

